/**
 * Visual questions on this device, from three places:
 *
 *   vis-<template>-<seed>   generated by the site (src/core/visual): rebuilt from the id
 *   vph-<photo>-<seed>      the public-domain photo set (data/visual/photos.json)
 *   vtm-<id>                visual questions the team added (synced team data)
 *
 * Inline SVG is only ever produced by the site's own generators: a figure is never taken from saved or
 * synced data as markup. Pictures come from the site's photo folder or are data: URLs of ordinary images.
 */
import type { Figure, Question, QuestionSet, Round, TeamVisual } from '../core/schema';
import { parseGeneratedId, questionForGeneratedId } from '../core/visual';
import { parsePhotoQuestionId, photoQuestion, type PhotoSet } from '../core/visual/photos';
import { getData } from './store';

export type VisualSource = 'generated' | 'photo' | 'team';

export function visualSourceOf(id: string): VisualSource | null {
  if (id.startsWith('vis-')) return 'generated';
  if (id.startsWith('vph-')) return 'photo';
  if (id.startsWith('vtm-')) return 'team';
  return null;
}

export function isVisualId(id: string): boolean {
  return visualSourceOf(id) !== null;
}

/** Pictures the site will show: its own photo files, or base64 data URLs of JPEG, PNG or WebP images. */
export function isSafeImageSrc(src: string): boolean {
  return /^data\/visual\/photos\/[a-z0-9-]+\.(webp|jpg|png)$/.test(src) || /^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$/.test(src);
}

/**
 * The figure to draw for a question, from trusted sources only: generated figures are rebuilt from the
 * question id; pictures must pass isSafeImageSrc. Anything else draws nothing.
 */
export function trustedFigure(q: Pick<Question, 'id' | 'figure'>): Figure | null {
  const fig = q.figure;
  if (!fig) return null;
  if (fig.kind === 'svg') {
    const rebuilt = parseGeneratedId(q.id) ? questionForGeneratedId(q.id)?.figure : undefined;
    return rebuilt?.kind === 'svg' ? rebuilt : null;
  }
  return isSafeImageSrc(fig.src) ? fig : null;
}

let photoPromise: Promise<PhotoSet> | null = null;

const EMPTY_PHOTOS: PhotoSet = { generatedAt: '', groups: [], photos: [] };

/** The photo set (empty if this build of the site has none). */
export function loadPhotoSet(): Promise<PhotoSet> {
  photoPromise ??= fetch('data/visual/photos.json')
    .then((res) => (res.ok ? (res.json() as Promise<PhotoSet>) : EMPTY_PHOTOS))
    .catch(() => {
      photoPromise = null;
      return EMPTY_PHOTOS;
    });
  return photoPromise;
}

/** A team visual as a question (its id is the record's id). */
export function teamVisualQuestion(v: TeamVisual): Question {
  return { ...v.question, id: v.id, kind: 'bonus', visual: true };
}

/** Find visual questions by id. Unknown ids are left out. */
export async function loadVisualQuestions(ids: string[]): Promise<Map<string, Question>> {
  const out = new Map<string, Question>();
  const photos = ids.some((id) => visualSourceOf(id) === 'photo') ? await loadPhotoSet() : EMPTY_PHOTOS;
  const team = new Map(getData().visuals.map((v) => [v.id, v]));
  for (const id of ids) {
    const source = visualSourceOf(id);
    let q: Question | null = null;
    if (source === 'generated') q = questionForGeneratedId(id);
    else if (source === 'photo') {
      const p = parsePhotoQuestionId(id);
      q = p ? photoQuestion(photos, p.photoId, p.seed) : null;
    } else if (source === 'team') {
      const v = team.get(id);
      q = v ? teamVisualQuestion(v) : null;
    }
    if (q) out.set(id, q);
  }
  return out;
}

/** Stand-ins for the library's set and round, so visual questions fit where library questions go. */
export const VISUAL_SET: QuestionSet = {
  id: 'visual',
  provider: 'rebound',
  level: 'HS',
  title: 'Visual bonuses',
  credit: 'Rebound visual bonuses',
  license: 'Generated figures: MIT License. Photos: public domain (see each photo).',
  rounds: [],
};

const ROUND_LABEL: Record<VisualSource, string> = { generated: 'generated', photo: 'photo set', team: 'added by the team' };

export function visualRound(id: string): Round {
  const source = visualSourceOf(id) ?? 'generated';
  return { id: `visual-${source}`, label: ROUND_LABEL[source], order: 0, pairs: [] };
}
